// Package auth says who a request is and what they may do.
package auth

import "example.com/tally/internal/store"

// Principal is the member a request acts for: the owner of the API key it presented, in that key's organization, with the
// member's current role.
type Principal struct {
	OrgID  string
	UserID string
	KeyID  string
	Role   store.Role
}

// Action is a kind of request an endpoint serves. Each endpoint requires one; Can says which roles may do it.
type Action int

// Actions.
const (
	// ActAny is for endpoints every member may use, viewers included. The handler checks anything narrower.
	ActAny Action = iota
	// ActRead reads customers, plans, subscriptions, invoices, payments, the organization, members and invites.
	ActRead
	// ActCustomerWrite creates, updates or deletes customers.
	ActCustomerWrite
	// ActSubscriptionWrite creates, updates or cancels subscriptions, and reports usage.
	ActSubscriptionWrite
	// ActPlanWrite creates or updates plans.
	ActPlanWrite
	// ActInvoiceWrite creates, pays or voids invoices.
	ActInvoiceWrite
	// ActRevenueReport reads the revenue report.
	ActRevenueReport
	// ActWebhooks manages webhook endpoints and reads their deliveries and the organization's events.
	ActWebhooks
	// ActOrgWrite updates the organization.
	ActOrgWrite
	// ActTeamWrite invites members, revokes invites, changes roles and removes members.
	ActTeamWrite
)

// Can reports whether a role may do an action.
func Can(r store.Role, a Action) bool {
	switch a {
	case ActAny, ActRead:
		return true
	case ActCustomerWrite, ActSubscriptionWrite:
		return r != store.RoleViewer
	case ActPlanWrite, ActInvoiceWrite, ActRevenueReport:
		return CanBill(r)
	case ActWebhooks, ActOrgWrite, ActTeamWrite:
		return CanManageTeam(r)
	}
	return false
}

// CanWrite reports whether a role may change anything. Viewers only read.
func CanWrite(r store.Role) bool { return r != store.RoleViewer }

// CanBill reports whether a role may manage billing: plans, invoices and the revenue report.
func CanBill(r store.Role) bool {
	return r == store.RoleOwner || r == store.RoleAdmin || r == store.RoleBilling
}

// CanManageTeam reports whether a role may manage the organization's settings, members and invites.
func CanManageTeam(r store.Role) bool { return r == store.RoleOwner || r == store.RoleAdmin }
EOF
