)

var allRoles = []store.Role{store.RoleOwner, store.RoleAdmin, store.RoleBilling, store.RoleMember, store.RoleViewer}

// wantForbidden checks that r refused the request: 403 and nothing but the error code.
func wantForbidden(t *testing.T, r *apitest.Response) {
	t.Helper()
	m := r.Map(t)
	if r.Code != http.StatusForbidden || len(m) != 1 || m["error"] != "forbidden" {
		t.Fatalf("want 403 {\"error\":\"forbidden\"}, got %s", r)
	}
}

// wantLastOwner checks that r refused the change because it would leave the organization without an owner.
func wantLastOwner(t *testing.T, r *apitest.Response) {
	t.Helper()
	m := r.Map(t)
	if r.Code != http.StatusConflict || len(m) != 1 || m["error"] != "last_owner" {
		t.Fatalf("want 409 {\"error\":\"last_owner\"}, got %s", r)
	}
}

// TestRoleMatrix sends each kind of endpoint as each role. A role outside the endpoint's list is refused with 403 forbidden;
// a role inside it is not refused for its role (the requests carry no real data, so the answer may be a 404 or 422).
func TestRoleMatrix(t *testing.T) {
	var (
		everyone = allRoles
		writers  = []store.Role{store.RoleOwner, store.RoleAdmin, store.RoleBilling, store.RoleMember}
		billers  = []store.Role{store.RoleOwner, store.RoleAdmin, store.RoleBilling}
		admins   = []store.Role{store.RoleOwner, store.RoleAdmin}
		owners   = []store.Role{store.RoleOwner}
	)
	tests := []struct {
		name, method, path string
		body               any
		roles              []store.Role
	}{
		{"me", "GET", "/v1/me", nil, everyone},
		{"list api keys", "GET", "/v1/api-keys", nil, everyone},
		{"create api key", "POST", "/v1/api-keys", map[string]string{"name": "k"}, everyone},
		{"revoke api key", "DELETE", "/v1/api-keys/key_nope", nil, everyone},
		{"leave", "DELETE", "/v1/members/usr_nope", nil, everyone},

		{"read org", "GET", "/v1/org", nil, everyone},
		{"read members", "GET", "/v1/members", nil, everyone},
		{"read invites", "GET", "/v1/invites", nil, everyone},
		{"update org", "PATCH", "/v1/org", map[string]string{"name": "X"}, admins},
		{"change a role", "PATCH", "/v1/members/usr_nope", map[string]string{"role": "member"}, admins},
		{"invite", "POST", "/v1/invites", map[string]string{"email": "a@example.com", "role": "member"}, admins},
		{"revoke invite", "DELETE", "/v1/invites/inv_nope", nil, admins},

		{"read customers", "GET", "/v1/customers", nil, everyone},
		{"export customers", "GET", "/v1/customers/export.csv", nil, everyone},
		{"read customer", "GET", "/v1/customers/cus_nope", nil, everyone},
		{"create customer", "POST", "/v1/customers", map[string]string{"name": "X", "email": "x@example.com"}, writers},
		{"update customer", "PATCH", "/v1/customers/cus_nope", map[string]string{"name": "X"}, writers},
		{"delete customer", "DELETE", "/v1/customers/cus_nope", nil, writers},

		{"read plans", "GET", "/v1/plans", nil, everyone},
		{"read plan", "GET", "/v1/plans/plan_nope", nil, everyone},
		{"create plan", "POST", "/v1/plans", map[string]string{"name": "X"}, billers},
		{"update plan", "PATCH", "/v1/plans/plan_nope", map[string]string{"name": "X"}, billers},

		{"read subscriptions", "GET", "/v1/subscriptions", nil, everyone},
		{"read subscription", "GET", "/v1/subscriptions/sub_nope", nil, everyone},
		{"create subscription", "POST", "/v1/subscriptions", map[string]string{"plan_id": "plan_nope"}, writers},
		{"update subscription", "PATCH", "/v1/subscriptions/sub_nope", map[string]string{"quantity": 2}, writers},
		{"cancel subscription", "POST", "/v1/subscriptions/sub_nope/cancel", nil, writers},
		{"report usage", "POST", "/v1/subscriptions/sub_nope/usage", map[string]int{"quantity": 1}, writers},

		{"read invoices", "GET", "/v1/invoices", nil, everyone},
		{"read invoice", "GET", "/v1/invoices/inv_nope", nil, everyone},
		{"read invoice lines", "GET", "/v1/invoices/inv_nope/lines", nil, everyone},
		{"read payments", "GET", "/v1/payments", nil, everyone},
		{"create invoice", "POST", "/v1/invoices", map[string]string{"customer_id": "cus_nope"}, billers},
		{"pay invoice", "POST", "/v1/invoices/inv_nope/pay", nil, billers},
		{"void invoice", "POST", "/v1/invoices/inv_nope/void", nil, billers},
		{"revenue report", "GET", "/v1/reports/revenue", nil, billers},

		{"list webhook endpoints", "GET", "/v1/webhook-endpoints", nil, admins},
		{"create webhook endpoint", "POST", "/v1/webhook-endpoints", map[string]string{"url": "https://hooks.acme.example/x"}, admins},
		{"read webhook endpoint", "GET", "/v1/webhook-endpoints/we_nope", nil, admins},
		{"update webhook endpoint", "PATCH", "/v1/webhook-endpoints/we_nope", map[string]string{"url": "https://hooks.acme.example/x"}, admins},
		{"delete webhook endpoint", "DELETE", "/v1/webhook-endpoints/we_nope", nil, admins},
		{"webhook deliveries", "GET", "/v1/webhook-endpoints/we_nope/deliveries", nil, admins},
		{"list events", "GET", "/v1/events", nil, admins},
		{"read event", "GET", "/v1/events/evt_nope", nil, admins},
	}
	_ = owners
	for _, tc := range tests {
		for _, role := range allRoles {
			t.Run(fmt.Sprintf("%s/%s", tc.name, role), func(t *testing.T) {
				e := apitest.New(t)
				_, key := e.AddMember(e.Acme, fmt.Sprintf("%s-role@acme.example", role), role)
				r := e.Do(tc.method, tc.path, key, tc.body)
				if slices.Contains(tc.roles, role) {
					if r.Code == http.StatusUnauthorized || r.Code == http.StatusForbidden {
						t.Fatalf("%s may %s %s: %s", role, tc.method, tc.path, r)
					}
					return
				}
				wantForbidden(t, r)
			})
		}
	}
}

// TestMemberRules covers who may change or remove whom, and the rule that an organization keeps an owner.
func TestMemberRules(t *testing.T) {
	e := apitest.New(t)
	owner := e.Acme.Owner
	ownerB, ownerBKey := e.AddMember(e.Acme, "owner-b@acme.example", store.RoleOwner)
	admin, adminKey := e.AddMember(e.Acme, "admin@acme.example", store.RoleAdmin)
	member, _ := e.AddMember(e.Acme, "member@acme.example", store.RoleMember)
	_, memberKey := e.AddMember(e.Acme, "member-two@acme.example", store.RoleMember)

	// Nobody changes their own role, not even an owner who is not the only one.
	wantForbidden(t, e.Do("PATCH", "/v1/members/"+ownerB.ID, ownerBKey, map[string]string{"role": "admin"}))
	wantForbidden(t, e.Do("PATCH", "/v1/members/"+admin.ID, adminKey, map[string]string{"role": "member"}))

	// Only an owner gives the owner or admin role, or changes or removes an owner or admin.
	wantForbidden(t, e.Do("PATCH", "/v1/members/"+member.ID, adminKey, map[string]string{"role": "admin"}))
	wantForbidden(t, e.Do("PATCH", "/v1/members/"+member.ID, adminKey, map[string]string{"role": "owner"}))
	wantForbidden(t, e.Do("PATCH", "/v1/members/"+owner.ID, adminKey, map[string]string{"role": "member"}))
	wantForbidden(t, e.Do("DELETE", "/v1/members/"+owner.ID, adminKey, nil))
	wantForbidden(t, e.Do("DELETE", "/v1/members/"+ownerB.ID, adminKey, nil))
	e.MustDo(http.StatusOK, "PATCH", "/v1/members/"+member.ID, adminKey, map[string]string{"role": "billing"}, nil)
	e.MustDo(http.StatusOK, "PATCH", "/v1/members/"+ownerB.ID, e.Acme.Key, map[string]string{"role": "owner"}, nil)
	e.MustDo(http.StatusOK, "PATCH", "/v1/members/"+member.ID, ownerBKey, map[string]string{"role": "admin"}, nil)
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/members/"+member.ID, ownerBKey, nil, nil)

	// Anyone may leave, and removing someone else is for owners and admins.
	wantForbidden(t, e.Do("DELETE", "/v1/members/"+admin.ID, memberKey, nil))
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/members/"+admin.ID, ownerBKey, nil, nil)
	if r := e.Do("GET", "/v1/me", adminKey, nil); r.Code != http.StatusUnauthorized {
		t.Fatalf("a removed admin's key: %s", r)
	}

	// The owner is now an admin, and the only owner is ownerB: they may not demote or remove themselves.
	e.MustDo(http.StatusOK, "PATCH", "/v1/members/"+owner.ID, ownerBKey, map[string]string{"role": "admin"}, nil)
	wantLastOwner(t, e.Do("PATCH", "/v1/members/"+ownerB.ID, ownerBKey, map[string]string{"role": "admin"}))
	wantLastOwner(t, e.Do("DELETE", "/v1/members/"+ownerB.ID, ownerBKey, nil))
	wantForbidden(t, e.Do("PATCH", "/v1/members/"+ownerB.ID, ownerBKey, map[string]string{"role": "owner"}))
	e.MustDo(http.StatusOK, "GET", "/v1/me", ownerBKey, nil, nil)
	if n := len(e.Store.Members(e.Acme.ID)); n != 3 {
		t.Fatalf("members = %d, want 3 (the refused changes must change nothing)", n)
	}

	// The former owner, now an admin, leaves.
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/members/"+owner.ID, e.Acme.Key, nil, nil)
	if r := e.Do("GET", "/v1/me", e.Acme.Key, nil); r.Code != http.StatusUnauthorized {
		t.Fatalf("a departed owner's key: %s", r)
	}
}

// TestInviteRoles checks that only an owner may invite someone as an admin.
func TestInviteRoles(t *testing.T) {
