// isOwnerOrAdmin reports whether a role is one only an owner may give, change or remove.
func isOwnerOrAdmin(r store.Role) bool { return r == store.RoleOwner || r == store.RoleAdmin }

func (s *Server) updateMember(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	var in struct {
		Role store.Role `json:"role"`
	}
	if !decode(w, r, &in) {
		return
	}
	userID := r.PathValue("user_id")
	if userID == p.UserID {
		// Nobody changes their own role. The organization's only owner is told last_owner instead, as demoting them
		// would leave it without one.
		if in.Role != store.RoleOwner && s.store.IsLastOwner(p.OrgID, userID) {
			s.storeError(w, store.ErrLastOwner)
			return
		}
		writeCode(w, http.StatusForbidden, "forbidden")
		return
	}
	// Only an owner may give the owner or admin role, or change the role of an owner or admin.
	if target, ok := s.store.Member(p.OrgID, userID); p.Role != store.RoleOwner && (isOwnerOrAdmin(in.Role) || (ok && isOwnerOrAdmin(target.Role))) {
		writeCode(w, http.StatusForbidden, "forbidden")
		return
	}
	m, err := s.store.SetMemberRole(p.OrgID, userID, in.Role)
	if err != nil {
		s.storeError(w, err)
		return
	}
	writeJSON(w, http.StatusOK, s.memberView(m))
}

func (s *Server) removeMember(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	userID := r.PathValue("user_id")
	if userID != p.UserID {
		// Anyone may leave; removing someone else is for owners and admins, and only an owner may remove an owner or admin.
		if !auth.CanManageTeam(p.Role) {
			writeCode(w, http.StatusForbidden, "forbidden")
			return
		}
		if target, ok := s.store.Member(p.OrgID, userID); ok && p.Role != store.RoleOwner && isOwnerOrAdmin(target.Role) {
			writeCode(w, http.StatusForbidden, "forbidden")
			return
		}
	}
	if err := s.store.RemoveMember(p.OrgID, userID); err != nil {
		s.storeError(w, err)
		return
	}
	w.WriteHeader(http.StatusNoContent)
}

