	e.MustDo(http.StatusCreated, "POST", "/v1/invites", e.Acme.Key, map[string]string{"email": "a@people.example", "role": "admin"}, nil)
}

// TestRoleChangesApplyToExistingKeys checks that a member's key takes the member's new role at once.
func TestRoleChangesApplyToExistingKeys(t *testing.T) {
	e := apitest.New(t)
	u, key := e.AddMember(e.Acme, "dev@acme.example", store.RoleMember)
	body := map[string]string{"name": "X", "email": "x@example.com"}
	e.MustDo(http.StatusCreated, "POST", "/v1/customers", key, body, nil)
	e.MustDo(http.StatusOK, "PATCH", "/v1/members/"+u.ID, e.Acme.Key, map[string]string{"role": "viewer"}, nil)
	wantForbidden(t, e.Do("POST", "/v1/customers", key, body))
	e.MustDo(http.StatusOK, "PATCH", "/v1/members/"+u.ID, e.Acme.Key, map[string]string{"role": "billing"}, nil)
	if r := e.Do("GET", "/v1/reports/revenue", key, nil); r.Code == http.StatusForbidden {
		t.Fatalf("billing may read the revenue report: %s", r)
	}
	e.MustDo(http.StatusOK, "PATCH", "/v1/members/"+u.ID, e.Acme.Key, map[string]string{"role": "member"}, nil)
	wantForbidden(t, e.Do("GET", "/v1/reports/revenue", key, nil))
}

// TestAPIKeyAccess covers who may list and revoke API keys.
func TestAPIKeyAccess(t *testing.T) {
	e := apitest.New(t)
	member, memberKey := e.AddMember(e.Acme, "member@acme.example", store.RoleMember)
	viewer, viewerKey := e.AddMember(e.Acme, "viewer@acme.example", store.RoleViewer)
	_, adminKey := e.AddMember(e.Acme, "admin@acme.example", store.RoleAdmin)
	ownerKey, _ := e.Store.APIKeyByToken(e.Acme.Key)
	viewerOwn, _ := e.Store.APIKeyByToken(viewerKey)

	// Everyone may create a key for themselves, and only the owner's caller sees every key.
	var laptop store.APIKey
	e.MustDo(http.StatusCreated, "POST", "/v1/api-keys", viewerKey, map[string]string{"name": "laptop"}, &laptop)
	var mine struct{ Items []store.APIKey }
	e.MustDo(http.StatusOK, "GET", "/v1/api-keys", viewerKey, nil, &mine)
	if len(mine.Items) != 2 {
		t.Fatalf("a viewer sees %d keys, want their own 2", len(mine.Items))
	}
	for _, k := range mine.Items {
		if k.UserID != viewer.ID {
			t.Fatalf("a viewer sees someone else's key: %+v", k)
		}
	}
	var all struct{ Items []store.APIKey }
	e.MustDo(http.StatusOK, "GET", "/v1/api-keys", adminKey, nil, &all)
	if len(all.Items) != 5 {
		t.Fatalf("an admin sees %d keys, want all 5", len(all.Items))
	}
	e.MustDo(http.StatusOK, "GET", "/v1/api-keys", memberKey, nil, &mine)
	if len(mine.Items) != 1 || mine.Items[0].UserID != member.ID {
		t.Fatalf("a member sees %+v, want only their own key", mine.Items)
	}

	// A member may not revoke the owner's key; the owner's key keeps working.
	wantForbidden(t, e.Do("DELETE", "/v1/api-keys/"+ownerKey.ID, memberKey, nil))
	e.MustDo(http.StatusOK, "GET", "/v1/org", e.Acme.Key, nil, nil)

	// A key of another organization is not found, whoever asks.
	globexKey, _ := e.Store.APIKeyByToken(e.Globex.Key)
	for _, key := range []string{memberKey, adminKey} {
		if r := e.Do("DELETE", "/v1/api-keys/"+globexKey.ID, key, nil); r.Code != http.StatusNotFound {
			t.Fatalf("revoke another organization's key: %s", r)
		}
	}

	// Everyone may revoke their own keys, and an admin may revoke anyone's.
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/api-keys/"+laptop.ID, viewerKey, nil, nil)
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/api-keys/"+viewerOwn.ID, adminKey, nil, nil)
	if r := e.Do("GET", "/v1/org", viewerKey, nil); r.Code != http.StatusUnauthorized {
		t.Fatalf("a revoked key: %s", r)
	}
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/api-keys/"+ownerKey.ID, adminKey, nil, nil)
	if r := e.Do("GET", "/v1/org", e.Acme.Key, nil); r.Code != http.StatusUnauthorized {
		t.Fatalf("the owner's revoked key: %s", r)
	}
}
