// TestMemberRoleGuards checks the rules about changing roles and removing members, against the roles as they are when
// the change is made: an admin promoted to owner's sight by a concurrent change must not be able to act on another admin.
func TestMemberRoleGuards(t *testing.T) {
	s := New()
	o := newOrg(t, s, "Acme")
	add := func(email string, role Role) Member {
		t.Helper()
		u, err := s.CreateUser(email, email, t0)
		if err != nil {
			t.Fatal(err)
		}
		m, err := s.AddMember(o.ID, u.ID, role, t0)
		if err != nil {
			t.Fatal(err)
		}
		return m
	}
	owner := add("owner@example.com", RoleOwner)
	admin := add("admin@example.com", RoleAdmin)
	target := add("target@example.com", RoleMember)
	ownerAct := Actor{UserID: owner.UserID, Role: RoleOwner}
	adminAct := Actor{UserID: admin.UserID, Role: RoleAdmin}

	// The owner promotes the target to admin. An admin's request, made with the role they had before, must now be refused:
	// the store reads the target's current role under its lock.
	if _, err := s.SetMemberRole(o.ID, ownerAct, target.UserID, RoleAdmin); err != nil {
		t.Fatal(err)
	}
	if _, err := s.SetMemberRole(o.ID, adminAct, target.UserID, RoleBilling); !errors.Is(err, ErrForbidden) {
		t.Fatalf("an admin demoted an admin: %v", err)
	}
	if err := s.RemoveMember(o.ID, adminAct, target.UserID); !errors.Is(err, ErrForbidden) {
		t.Fatalf("an admin removed an admin: %v", err)
	}
	if _, ok := s.Member(o.ID, target.UserID); !ok {
		t.Fatal("a refused removal removed the member")
	}

	// Only an owner gives the owner or admin role, and only an owner changes or removes an owner or admin.
	if _, err := s.SetMemberRole(o.ID, adminAct, owner.UserID, RoleMember); !errors.Is(err, ErrForbidden) {
		t.Fatalf("an admin demoted an owner: %v", err)
	}
	if err := s.RemoveMember(o.ID, adminAct, owner.UserID); !errors.Is(err, ErrForbidden) {
		t.Fatalf("an admin removed an owner: %v", err)
	}
	if _, err := s.SetMemberRole(o.ID, adminAct, target.UserID, RoleOwner); !errors.Is(err, ErrForbidden) {
		t.Fatalf("an admin made an owner: %v", err)
	}

	// Nobody changes their own role. A viewer may not remove someone who does not exist, and is not told so.
	if _, err := s.SetMemberRole(o.ID, adminAct, admin.UserID, RoleMember); !errors.Is(err, ErrForbidden) {
		t.Fatalf("an admin changed their own role: %v", err)
	}
	viewer := Actor{UserID: "usr_viewer", Role: RoleViewer}
	if err := s.RemoveMember(o.ID, viewer, "usr_nope"); !errors.Is(err, ErrForbidden) {
		t.Fatalf("a viewer removed someone: %v", err)
	}

	// Anyone may leave, and an owner may remove an admin.
	if err := s.RemoveMember(o.ID, Actor{UserID: target.UserID, Role: RoleAdmin}, target.UserID); err != nil {
		t.Fatalf("a member could not leave: %v", err)
	}
	if err := s.RemoveMember(o.ID, ownerAct, admin.UserID); err != nil {
		t.Fatalf("an owner could not remove an admin: %v", err)
	}

	// The only owner may not demote or remove themselves.
	if _, err := s.SetMemberRole(o.ID, ownerAct, owner.UserID, RoleAdmin); !errors.Is(err, ErrLastOwner) {
		t.Fatalf("the only owner demoted themselves: %v", err)
	}
	if err := s.RemoveMember(o.ID, ownerAct, owner.UserID); !errors.Is(err, ErrLastOwner) {
		t.Fatalf("the only owner removed themselves: %v", err)
	}
	if n := len(s.Members(o.ID)); n != 1 {
		t.Fatalf("members = %d, want 1: refused changes must change nothing", n)
	}
}

