// SetMemberRole changes a member's role.
func (s *Store) SetMemberRole(orgID, userID string, role Role) (Member, error) {
	if !role.Valid() {
		return Member{}, invalid("unknown role %q", role)
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	k := memberKey{orgID, userID}
	m, ok := s.members[k]
	if !ok {
		return Member{}, ErrNotFound
	}
	m.Role = role
	s.members[k] = m
	return m, nil
}

// Actor is the member making a change to membership, with the role they had when the request arrived.
type Actor struct {
	UserID string
	Role   Role
}

// SetMemberRoleAs changes a member's role on behalf of an actor. The rules about who may change whose role are checked
// here, under the same lock as the change, so they see the roles as they are now. It returns ErrForbidden when the actor
// may not make the change, and ErrLastOwner when that would demote the organization's only owner.
func (s *Store) SetMemberRoleAs(orgID string, actor Actor, userID string, role Role) (Member, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	k := memberKey{orgID, userID}
	m, ok := s.members[k]
	if actor.UserID == userID {
		// Nobody changes their own role. The only owner is told ErrLastOwner instead, as demoting them would leave none.
		if ok && role != RoleOwner && m.Role == RoleOwner && s.ownerCount(orgID) == 1 {
			return Member{}, ErrLastOwner
		}
		return Member{}, ErrForbidden
	}
	// Only an owner may give the owner or admin role, or change the role of an owner or admin.
	if actor.Role != RoleOwner && (isOwnerOrAdmin(role) || (ok && isOwnerOrAdmin(m.Role))) {
		return Member{}, ErrForbidden
	}
	if !ok {
		return Member{}, ErrNotFound
	}
	if !role.Valid() {
		return Member{}, invalid("unknown role %q", role)
	}
	if m.Role == RoleOwner && role != RoleOwner && s.ownerCount(orgID) == 1 {
		return Member{}, ErrLastOwner
	}
	m.Role = role
	s.members[k] = m
	return m, nil
}

// RemoveMember removes a user from an organization. Their API keys for it stop working, as they are no longer a member.
func (s *Store) RemoveMember(orgID, userID string) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	k := memberKey{orgID, userID}
	if _, ok := s.members[k]; !ok {
		return ErrNotFound
	}
	delete(s.members, k)
	return nil
}

// RemoveMemberAs removes a user on behalf of an actor. Anyone may leave. Removing someone else is for owners and admins,
// and only an owner may remove an owner or admin. It returns ErrForbidden when the actor may not make the removal, and
// ErrLastOwner when that would remove the organization's only owner.
func (s *Store) RemoveMemberAs(orgID string, actor Actor, userID string) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	k := memberKey{orgID, userID}
	m, ok := s.members[k]
	if actor.UserID != userID {
		if !isOwnerOrAdmin(actor.Role) || (actor.Role != RoleOwner && ok && isOwnerOrAdmin(m.Role)) {
			return ErrForbidden
		}
	}
	if !ok {
		return ErrNotFound
	}
	if m.Role == RoleOwner && s.ownerCount(orgID) == 1 {
		return ErrLastOwner
	}
	delete(s.members, k)
	return nil
}
